import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Admin Login & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-login.md","filePath":"guide/admin-login.md","lastUpdated":1790683574000}'),i={name:"guide/admin-login.md"};function s(r,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="admin-login-permissions" tabindex="-1">Admin Login &amp; Permissions <a class="header-anchor" href="#admin-login-permissions" aria-label="Permalink to &quot;Admin Login &amp; Permissions&quot;">​</a></h1><h2 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h2><p>The admin console requires an administrator account, and a captcha must be entered at login.</p><p>The platform supports <strong>Google two-factor authentication (2FA)</strong>: once enabled, after entering the username and password, an administrator must also enter the one-time code from Google Authenticator to access the console. This switch is controlled in the admin configuration.</p><div class="warning custom-block"><p class="custom-block-title">Recommendation</p><p>Admin accounts are the highest-privilege entry point of the platform. <strong>We strongly recommend enabling Google 2FA</strong> and giving each operator their own account instead of sharing accounts.</p></div><p>Accounts with too many failed attempts are temporarily locked; password recovery also has a failed-attempt limit.</p><h2 id="permission-model" tabindex="-1">Permission model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission model&quot;">​</a></h2><p>The admin console uses a <strong>role + menu permission</strong> model:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Admin account  →  assigned roles  →  roles decide which menus are visible and which actions are allowed</span></span></code></pre></div><ul><li>Create roles and tick permissions under &quot;System Management → Role Management&quot;</li><li>Assign roles to administrators under &quot;System Management → User Management&quot;</li><li>Menus that are not authorized do not appear in that account&#39;s console</li></ul><h2 id="super-admin-only-settings" tabindex="-1">Super-admin-only settings <a class="header-anchor" href="#super-admin-only-settings" aria-label="Permalink to &quot;Super-admin-only settings&quot;">​</a></h2><p>Some settings <strong>can only be changed by a super administrator</strong>; ordinary operator roles cannot save them even if they can access the configuration menu. This is intentional — a mistaken or malicious change to these settings has <strong>security-level or platform-wide</strong> consequences:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Consequence of a wrong change</th></tr></thead><tbody><tr><td>Deposit channel</td><td>Incoming funds may be redirected</td></tr><tr><td>Withdrawal channel</td><td>Outgoing funds flow breaks</td></tr><tr><td>Third-party deposit/withdrawal channel</td><td>Same as above</td></tr><tr><td>Payment gateway selection</td><td>Wrong deposit channel in use</td></tr><tr><td>Payment channel keys</td><td>Funds security</td></tr><tr><td>Admin login 2FA switch</td><td>Turns off 2FA protection for the console</td></tr><tr><td>Admin IP allowlist</td><td>Removes restrictions on where the console can be accessed from</td></tr><tr><td>Market data source</td><td>Prices may come from the wrong service, affecting execution prices</td></tr><tr><td>Exchange rates</td><td>Instruments priced in other currencies (e.g. HK or China A-shares) execute at a wrongly scaled price</td></tr><tr><td>App version update</td><td>The force-update switch can lock every user on an old version out of the app. See <a href="/CoinExchange/guide/app-release">App Releases</a></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Please note</p><p><strong>Avoid changing the settings above during peak business hours.</strong> Make sure you understand each setting before changing it, and check with your technical team if needed.</p></div><h2 id="suggested-division-of-accounts" tabindex="-1">Suggested division of accounts <a class="header-anchor" href="#suggested-division-of-accounts" aria-label="Permalink to &quot;Suggested division of accounts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Suggested permissions</th></tr></thead><tbody><tr><td>Super administrator</td><td>Everything. Held by only 1–2 people, for configuration work</td></tr><tr><td>Finance</td><td>Deposit records, withdrawal review, ledger, fund sweeping</td></tr><tr><td>Customer service</td><td>User lookup, KYC review, help center and announcements, chat history</td></tr><tr><td>Operations</td><td>Site configuration (excluding the super-admin items above), coin management, product configuration, dashboards</td></tr></tbody></table>',16)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
